{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Practical mental health membership</title>
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="logo" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="index.html">Home</a>
        <a href="about.html">Practice</a>
        <a href="specialties.html">Focus Areas</a>
        <a href="approach.html">Way of Working</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html">Common Qs</a>
        <a class="cta" href="book.html">Start</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero split-diagonal" id="hero">
      <div class="hero-left">
        <h1 class="title">Steady support for ordinary days and the moments that matter.</h1>
        <p class="lede">A membership-based practice offering regular sessions, flexible check-ins, and structured planning to help you manage stress, relationships, and transitions with clinical care that respects your pace.</p>
        <p class="meta">Starts with a consultation. Confidential. Clinician-led. No guarantees — collaborative, evidence-informed support.</p>
        <div class="hero-actions">
          <a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="ghost" href="#planner">Session Planner</a>
        </div>
      </div>
      <div class="hero-right" aria-hidden="true">
        <svg class="pattern" viewBox="0 0 600 400" preserveAspectRatio="none">
          <defs>
            <pattern id="diag" patternUnits="userSpaceOnUse" width="40" height="40">
              <rect width="40" height="40" fill="#f7fbfb" />
              <path d="M-10,10 l20,-20 M0,40 l40,-40 M30,50 l20,-20" stroke="#e6f0f0" stroke-width="2" />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#diag)" />
        </svg>
      </div>
    </section>

    <section class="membership" id="membership">
      <div class="wrap">
        <h2>Membership care, described plainly</h2>
        <p>Members choose a recurring weekly or biweekly rhythm and receive a calm, organized plan for progress. Sessions are 50 minutes; messaging check-ins are available within agreed boundaries. Not a crisis service — see the footer for emergency guidance.</p>
        <div class="plans">
          <article class="plan">
            <h3>Foundation Circle</h3>
            <p class="price">Monthly membership — flexible scheduling</p>
            <ul>
              <li>One 50-minute session every two weeks</li>
              <li>Brief secure messages between sessions (limited)</li>
              <li>Quarterly planning review</li>
            </ul>
            <a class="small-cta" href="fees.html">View details</a>
          </article>

          <article class="plan">
            <h3>Steady Care</h3>
            <p class="price">Monthly membership — weekly option</p>
            <ul>
              <li>One 50-minute session every week</li>
              <li>Structured session summaries and action steps</li>
              <li>Flexible scheduling within membership limits</li>
            </ul>
            <a class="small-cta" href="fees.html">View details</a>
          </article>
        </div>
      </div>
    </section>

    <section class="planner" id="planner">
      <div class="wrap">
        <h2>Session Planner</h2>
        <p>Build a short plan to shape your first few sessions. Copy it into your notes, or bring it to your consultation.</p>

        <form id="plannerForm" class="planner-form" onsubmit="return false;">
          <label>Primary focus for sessions
            <select id="focus">
              <option value="stress">Stress management & daily energy</option>
              <option value="relationships">Relationships & communication</option>
              <option value="grief">Loss, change, or transitions</option>
              <option value="work">Work or career-related challenges</option>
              <option value="other">Other — personal goals</option>
            </select>
          </label>

          <label>Session rhythm
            <select id="rhythm">
              <option value="biweekly">Every two weeks</option>
              <option value="weekly">Once per week</option>
              <option value="monthly">Monthly check-in</option>
            </select>
          </label>

          <label>Therapeutic emphasis
            <select id="style">
              <option value="skills">Skills & coping strategies</option>
              <option value="exploratory">Exploratory & reflective</option>
              <option value="brief">Goal-focused, brief work</option>
              <option value="mixture">Mixture of practical and reflective</option>
            </select>
          </label>

          <label>Two short goals (comma separated)
            <input id="goals" placeholder="e.g., reduce evening worry, improve sleep routine">
          </label>

          <div class="planner-actions">
            <button id="buildPlan" class="primary">Create plan</button>
            <button id="clearPlan" class="ghost" type="button">Clear</button>
          </div>
        </form>

        <div class="output">
          <h3>Your draft plan</h3>
          <pre id="planOutput" tabindex="0">Use the form to create a personalized plan.</pre>
          <div class="output-actions">
            <button id="copyPlan">Copy summary</button>
            <a href="book.html" class="small-cta">Bring this to consultation</a>
          </div>
        </div>
      </div>
    </section>

    <section class="intake-wizard" id="wizard">
      <div class="wrap">
        <h2>Self-screening intake wizard</h2>
        <p>This is not a diagnostic tool. It helps you gather details to share at your first appointment. Responses are private on your device only.</p>

        <div id="wizardApp">
          <div class="step" data-step="1">
            <h4>Step 1 — Current concerns</h4>
            <label>Which of these feel most relevant now?</label>
            <div class="checks">
              <label><input type="checkbox" value="anxiety"> Feelings of worry or tension</label>
              <label><input type="checkbox" value="low_mood"> Low mood or reduced interest</label>
              <label><input type="checkbox" value="sleep"> Sleep difficulties</label>
              <label><input type="checkbox" value="relationships"> Relationship strain</label>
              <label><input type="checkbox" value="work"> Work or performance concerns</label>
              <label><input type="checkbox" value="other"> Other</label>
            </div>
            <div class="wizard-actions">
              <button class="next">Next</button>
            </div>
          </div>

          <div class="step" data-step="2" style="display:none;">
            <h4>Step 2 — What helps or doesn’t help</h4>
            <label>Briefly note strategies you’ve tried
              <input id="tried" placeholder="e.g., breathing exercises, journaling, medication discussions">
            </label>
            <label>Anything that makes things worse?
              <input id="worse" placeholder="e.g., caffeine, isolation">
            </label>
            <div class="wizard-actions">
              <button class="back">Back</button>
              <button class="next">Next</button>
            </div>
          </div>

          <div class="step" data-step="3" style="display:none;">
            <h4>Step 3 — Goals and supports</h4>
            <label>What would you most like to see change in 3 months?
              <input id="threeMonths" placeholder="e.g., feel less overwhelmed, sleep more consistently">
            </label>
            <label>Who supports you now? (optional)
              <input id="supports" placeholder="e.g., partner, friend, colleague">
            </label>
            <div class="wizard-actions">
              <button class="back">Back</button>
              <button id="finishWizard" class="primary">Finish</button>
            </div>
          </div>

          <div id="wizardOutput" style="display:none;">
            <h3>Notes to bring to the consultation</h3>
            <pre id="wizardSummary" tabindex="0"></pre>
            <div class="output-actions">
              <button id="copyWizard">Copy notes</button>
              <a class="small-cta" href="book.html">Schedule consult</a>
            </div>
          </div>

        </div>

      </div>
    </section>

    <section class="what-to-expect" id="what">
      <div class="wrap">
        <h2>What to expect in early sessions</h2>
        <ol>
          <li>We clarify what matters most to you and set practical short-term aims.</li>
          <li>We use a mix of reflection, skill-building, and planning tailored to your needs.</li>
          <li>We review and adjust the plan regularly — you remain in control of pace and priorities.</li>
        </ol>
      </div>
    </section>

    <section class="objections" id="objections">
      <div class="wrap">
        <h2>Common questions</h2>
        <details><summary>How does membership billing work?</summary>
          <p>Membership is billed monthly. Each plan outlines frequency and included items. Additional services are described in the Investment page.</p>
        </details>
        <details><summary>Is our work confidential?</summary>
          <p>Yes. Information shared in sessions is confidential within legal and ethical limits. Exceptions include imminent risk of harm to self or others, or when required by law — we discuss these boundaries during intake.</p>
        </details>
        <details><summary>What if I need help right away?</summary>
          <p>This practice is not an emergency service. If you are in crisis or at immediate risk, contact local emergency services or a crisis line in your area. See contact page for local resources.</p>
        </details>
      </div>
    </section>

    <section class="cta" id="final-cta">
      <div class="wrap">
        <h2>Ready to begin?</h2>
        <p>Start with a short consultation to see if membership fits your needs. We’ll co-create a plan that fits your life.</p>
        <a class="primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>

      <div>
        <h4>Clinical boundaries</h4>
        <p>Sessions are private and guided by professional ethics. This practice does not provide forensic, legal, or emergency services. If you are experiencing an emergency, please call local emergency services or your nearest crisis line immediately.</p>
      </div>

      <div>
        <h4>Policies</h4>
        <ul>
          <li><a href="fees.html">Fees & scheduling</a></li>
          <li><a href="faq.html">Common questions</a></li>
          <li><a href="contact.html">Privacy & contact</a></li>
        </ul>
      </div>
    </div>
    <div class="legal">
      <p>Confidentiality is maintained except where disclosure is required by law or to prevent imminent harm. Content on this site is for informational purposes and not a substitute for a professional consultation.</p>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
